/* Editorial English edition of the portfolio. No third-party translation service. */
window.PortfolioEN = (() => {

const schedulingIllustration=(kind,en=false)=>{
 const zh={
  continuity:['學生課程','主要老師','代課老師','主要老師','主要老師'],
  authority:['學生時段','課程間隔','老師分配','排課草案','老師檢查與調整'],
  changing:['初次排課','臨時請假','尋找代課／補課','更新課表'],
  adoption:['自動產生課表','新工具學習','異動維護','整體負擔待驗證'],
  collaboration:['學生','主要老師','代課老師','LINE 協作與通知']
 };
 const english={
  continuity:['Student lessons','Main teacher','Substitute','Main teacher','Main teacher'],
  authority:['Availability','Lesson spacing','Teacher assignment','Draft timetable','Instructor reviews and adjusts'],
  changing:['Initial plan','Absence','Find cover / make-up','Update schedule'],
  adoption:['Auto-generated plan','Tool onboarding','Change upkeep','Total effort unverified'],
  collaboration:['Student','Main instructor','Substitute','LINE communication']
 };
 const v=(en?english:zh)[kind];
 let inside='';
 if(kind==='continuity')inside='<div class="schedule-scene-label">'+v[0]+'</div><div class="schedule-scene-lessons">'+v.slice(1).map((t,i)=>'<div class="'+(i===1?'substitute':'')+'"><span>'+(i+1).toString().padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='authority')inside='<div class="schedule-scene-constraints">'+v.slice(0,3).map(t=>'<span>'+t+'</span>').join('')+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-draft">'+v[3]+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-decision">'+v[4]+' ✓</div>';
 if(kind==='changing')inside='<div class="schedule-scene-stages">'+v.map((t,i)=>'<div class="'+(i===1?'changed':'')+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='adoption')inside='<div class="schedule-scene-work"><div><span>−</span><strong>'+v[0]+'</strong></div><div><span>+</span><strong>'+v[1]+'</strong></div><div><span>+</span><strong>'+v[2]+'</strong></div></div><div class="schedule-scene-decision">'+v[3]+'</div>';
 if(kind==='collaboration')inside='<div class="schedule-scene-people">'+v.slice(0,3).map((t,i)=>'<div><span class="person-avatar">'+['●','◆','●'][i]+'</span><strong>'+t+'</strong></div>').join('')+'</div><div class="schedule-scene-links">↕　↕　↕</div><div class="schedule-scene-decision">'+v[3]+'</div>';
 return '<div class="schedule-scene schedule-scene--'+kind+'" aria-hidden="true">'+inside+'</div>';
};
const schedulingInsight=(num,label,title,copy,kind,caption,en=false)=>'<article class="schedule-insight-card"><div class="schedule-insight-copy"><div class="schedule-insight-heading"><em>'+num+'</em><span>'+label+'</span></div><h4>'+title+'</h4><p>'+copy+'</p></div><figure class="schedule-insight-figure">'+schedulingIllustration(kind,en)+'<figcaption>'+caption+'</figcaption></figure></article>';

 const section=(id,n,label,title,body)=>`<section class="story-section" id="${id}"><div class="story-kicker">${n} / ${label}</div><h2>${title}</h2>${body}</section>`;
 const p=t=>`<p>${t}</p>`;
 const img=(file,alt,caption,cls='')=>`<figure class="${cls||'english-figure'}"><img loading="lazy" src="./${file}" alt="${alt}"><figcaption>${caption}</figcaption></figure>`;
 const evidence=(tag,title,copy)=>`<div class="english-evidence"><span>${tag}</span><h3>${title}</h3><p>${copy}</p></div>`;
 const two=(a,b)=>`<div class="english-pair">${a}${b}</div>`;
 const nav={scheduling:['Overview','Problem Discovery','Product Strategy','Workflow & Rules','Design Highlights','Validation','Reflection'],kiosk:['Overview','Research Framework','Research Findings','Recommendations','Design & Validation','Outcome'],kds:['Context','Discovery','User Analysis','Product Decisions','Independent Design','Reflection']};
 const content={
 scheduling:()=>
 section('overview','01','PROJECT OVERVIEW','I built a working scheduling product—then learned to rethink what was worth building first',
  '<div class="story-arc"><div><span>01 / PROBLEM</span><strong>2–3 hours of scheduling a month</strong><p>Plus repeated rescheduling after cancellations.</p></div><div><span>02 / BUILD</span><strong>I built a working system</strong><p>Students submit times, the system drafts, the instructor decides.</p></div><div><span>03 / TURN</span><strong>The demo revealed the real barrier</strong><p>Her concern was adoption and upkeep, not scheduling speed.</p></div><div><span>04 / LEARNING</span><strong>Validate shared needs before adding features</strong><p>This case is also a record of how I re-scoped the MVP.</p></div></div>'+
  p('This independent project began with a Pilates instructor’s real challenge: building the monthly timetable takes approximately 2–3 hours, followed by frequent cancellations and changes. She collects availability in LINE, arranges classes on paper, and coordinates substitute teachers in a group chat. The challenge involves not only finding open slots but making trade-offs and managing ongoing coordination.')+
  '<div class="schedule-feature-quote"><span>DESIGN QUESTION</span><strong>How might we respect each student’s availability, balance fairness and teaching continuity, and help the instructor plan an entire month efficiently?</strong></div>'+
  '<figure class="scenario-figure pilates-case-scenario"><img loading="eager" decoding="async" fetchpriority="high" width="2048" height="1536" src="./assets/pilates-scenario.webp" alt="Composite lifestyle scene of a Pilates instructor viewing the scheduling system on her phone"><figcaption>Use scenario (composite image).</figcaption></figure>')+
 section('research','02','PROBLEM DISCOVERY','The problem goes beyond scheduling time: balancing different constraints',
  '<div class="schedule-problem-grid">'+evidence('INSTRUCTOR / REPORTED','One-to-one coordination concentrates the work on the instructor','She must collect availability, balance lessons with the primary instructor, allow intervals between sessions, and coordinate substitutes. Initial planning takes 2–3 hours per month, with further cancellations and changes.')+evidence('STUDENTS / INSTRUCTOR REPORTED','First-come-first-served is not the preferred solution','The instructor previously tried student self-booking, but observed more cancellations and returned to instructor-led scheduling.')+'</div>'+
  '<h3>Initial assumptions before building | Source: one instructor</h3>'+
  schedulingInsight('01','TEACHING CONTINUITY','Scheduling quality depends not only on lesson counts, but on continuity with the primary instructor.','The instructor values regular lessons with the primary teacher. Allocation should preserve continuity rather than simply maximize the number of sessions.','continuity','Lesson pattern with a primary and a substitute teacher.',true)+
  schedulingInsight('02','DECISION AUTHORITY','Multiple constraints and exceptions resist full automation; the instructor must retain final authority.','Availability, lesson spacing, and instructor assignment can conflict. The system should propose a draft and surface conflicts for human review.','authority','Multiple constraints; the draft still needs the instructor’s review.',true)+
  schedulingInsight('03','CONTINUOUS COORDINATION','Scheduling is not a one-time allocation; absences, make-up lessons, and substitute needs keep it changing.','The first timetable is only a starting point. Later changes require renewed coordination and updated information across participants.','changing','Illustrative change sequence showing ongoing coordination.',true)+
  '<p class="schedule-insight-disclaimer">These three points were assumptions formed from conversations with one instructor before I started building. Section 07 revisits them—some held up, and the demo overturned others.</p>'+'<div class="schedule-turn"><span>PRODUCT FRAMING / REFRAMING THE PROBLEM</span><p>The core problem is not “how do students book faster?” but <strong>“how do we fairly allocate lessons students can accept while giving the instructor flexibility to adjust the monthly timetable?”</strong></p></div>')+
 section('opportunity','03','PRODUCT STRATEGY','Product strategy: collect acceptable times, then allocate centrally',
  p('I did not default to student self-booking. The instructor had tried it and reported more cancellations while student needs were harder to balance. Instead, students submit acceptable times, the system generates a month-wide draft, and the instructor reviews and confirms it. Rules consider primary-instructor lesson targets, availability, and total scheduled sessions.')+
  '<div class="schedule-comparison"><div class="schedule-compare-old"><span>BEFORE / FIRST COME, FIRST SERVED</span><h3>Whoever clicks first gets the slot</h3><p>Students compete for popular times. Individual bookings may be easier to complete, but overall needs can be overlooked.</p></div><div class="schedule-compare-new"><span>DESIGN DIRECTION / PREFERENCE-BASED ALLOCATION</span><h3>See what everyone can accept first</h3><p>Students submit acceptable times; the system generates a draft for the instructor to adjust and approve.</p></div></div>'+
  '<div class="schedule-preference"><div class="schedule-preference-title"><span>DESIGN PRINCIPLE 01</span><h3>“Acceptable” does not mean “you must offer more choices”</h3><p>Someone may only select Tuesday—that restriction is respected. Choosing more days creates flexibility, but no student is forced to loosen their boundaries for the algorithm.</p></div><div class="schedule-choice-demo" aria-label="Conceptual student availability example"><span>STUDENT A / AVAILABLE DAY</span><div class="schedule-days"><i>Mon</i><i class="picked">Tue ✓</i><i>Wed</i><i>Thu</i><i>Fri</i><i>Sat</i><i>Sun</i></div><small>Concept: this student only accepts Tuesday.</small></div></div>')+
 section('solutions','04','EXPERIENCE & RULES','Designing an editable workflow from real scheduling rules',
  '<div class="schedule-flow"><div><span>01 / INPUT</span><h3>Students submit acceptable times</h3><p>Students provide their own constraints instead of the instructor collecting each schedule manually.</p></div><div><span>02 / DRAFT</span><h3>The system builds a timetable draft</h3><p>It allocates lessons against student constraints and available teaching hours for a whole-month review.</p></div><div><span>03 / REVIEW</span><h3>The instructor handles exceptions</h3><p>Assignments remain editable. Unscheduled students and reasons are retained for manual resolution.</p></div><div><span>04 / CONFIRM</span><h3>Confirm and stabilize the timetable</h3><p>Once scheduling is finalized, students cannot independently cancel existing classes; the instructor handles subsequent changes.</p></div></div>'+
  '<div class="schedule-decision-grid">'+evidence('DESIGN PRINCIPLE 02','Review the timetable from a student-centered perspective','The same schedule can be reviewed as a complete instructor calendar or a single student’s lessons. The instructor can inspect assigned and available times, move sessions, fill missing lessons, and assign substitutes.')+evidence('DESIGN PRINCIPLE 03','Keep final authority with the instructor','The scheduling logic considers primary-teacher lesson targets, student coverage, limited availability, and a preferred three-day gap between classes. Unassigned lessons and reasons remain visible for human decisions.')+'</div>')+
 section('highlights','05','DESIGN HIGHLIGHTS','Three design highlights: from scheduling rules to cross-role coordination','<p class="schedule-highlight-intro">These three designs turn an instructor\'s tacit scheduling judgment, role-specific information needs, and ongoing substitute coordination into usable interfaces. Screens below are from the first product version with demo data.</p>'+'<article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">01 / FROM MENTAL MODEL TO SCHEDULING RULES</span><h3>Making the instructor’s scheduling judgments visible as rules</h3><dl><div><dt>PROBLEM</dt><dd>Beyond availability, scheduling must consider remaining lessons, spacing, instructor continuity, and conflicts. Previously, many tradeoffs lived in the instructor’s experience.</dd></div><div><dt>DESIGN</dt><dd>Break those judgments into editable criteria and priorities, such as covering each student\'s minimum lessons before filling remaining sessions.</dd></div><div><dt>INTERACTION</dt><dd>The instructor inspects rules, generates a draft, then reviews states such as incomplete, submitted, and shared before confirming.</dd></div></dl><p class="hl-skills">UX Research × Domain Modeling × Rule-based Product Design</p><a class="hl-try" href="#try-demo" data-demo-go="pil-result">Try it in free play <span aria-hidden="true">↓</span></a></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-p1.jpg?v=2"><source src="./assets/pilates-hl-p1.mp4?v=2" type="video/mp4"></video></div><figcaption>Start → auto-schedule → confirm and share, pick recipients in LINE, then it shows as shared</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">02 / SWITCHING BETWEEN STUDENT AND TEACHER VIEWS</span><h3>Zooming from one student to the whole instructor week</h3><dl><div><dt>PROBLEM</dt><dd>A student\'s calendar alone cannot reveal the instructor\'s full capacity; a whole-week calendar alone can obscure an individual student\'s constraints.</dd></div><div><dt>DESIGN</dt><dd>Provide student-month and instructor-week views over the same scheduling information, allowing reviews at both individual and system levels.</dd></div><div><dt>INTERACTION</dt><dd>Search for a student and check scheduled sessions and availability, then open the instructor\'s weekly overview to assess overall occupancy.</dd></div></dl><p class="hl-skills">Information Architecture × Interaction Design</p><a class="hl-try" href="#try-demo" data-demo-go="pil-week">Try it in free play <span aria-hidden="true">↓</span></a></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-p2.jpg?v=2"><source src="./assets/pilates-hl-p2.mp4?v=2" type="video/mp4"></video></div><figcaption>A student’s available times, then the instructor’s whole week</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">03 / SUBSTITUTE & FREED-SLOT COORDINATION</span><h3>From manually finding replacements to surfacing candidates</h3><dl><div><dt>PROBLEM</dt><dd>Absences and substitutes require renewed checks on who is available, what remains unassigned, and which teachers need coordinating.</dd></div><div><dt>DESIGN</dt><dd>Gather substitute needs into a searchable, shareable list and surface students who previously selected a newly freed time slot.</dd></div><div><dt>INTERACTION</dt><dd>Use the substitute overview and LINE sharing for cross-instructor coordination; after a slot opens, the instructor may choose an eligible student. This is not fully automated notification.</dd></div></dl><p class="hl-skills">Workflow Design × Service Coordination</p></div><figure class="hl-clip hl-clip--shots"><div class="hl-shot-pair"><img loading="lazy" src="./assets/pilates-design-03a.webp" alt="Substitute overview with LINE sharing"><img loading="lazy" src="./assets/pilates-design-03b.webp" alt="Freed-slot candidates"></div><figcaption>Substitute overview and freed-slot screens (screenshots)</figcaption></figure></article>'+'<p class="schedule-highlight-note">Source: first-version product screenshots; student names are test records.</p><div class="schedule-live-demo" id="try-demo"><div class="schedule-live-copy"><span>TRY THE PRODUCT / INTERACTIVE DEMO</span><h3>The production flow, without the LINE login</h3><p>This runs the production product’s code and flow with only the LINE login removed and sample data in its place: all 10 sample students have already submitted their times, so you can go straight to the key flow: start scheduling, review responses, run auto-scheduling, then use “confirm and share” next to a student to pick a LINE group or student in a simulated LINE share picker. Use the Instructor / Student switch above the phone to change views.</p><a href="./pilates-demo/teacher/" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · LINE sharing is simulated and nothing is sent · Reload to reset the sample data</small></div><div class="schedule-live-stage"><div class="pil-view-switch" role="tablist" aria-label="切換視角"><button type="button" role="tab" data-pil-view="teacher" aria-selected="true">👩‍🏫 Instructor</button><button type="button" role="tab" data-pil-view="student" aria-selected="false">🙋‍♀️ Student</button></div><div class="schedule-live-frame"><iframe data-pil-frame="teacher" src="./pilates-demo/teacher/" title="Pilates scheduling instructor demo" loading="lazy"></iframe><iframe data-pil-frame="student" data-src="./pilates-demo/?t=t1" title="Pilates scheduling student demo" hidden></iframe></div></div></div>')+
 section('validation','06','FROM IDEA TO PRODUCT','Building the MVP: from product rules to tests and instructor feedback',
  ''+
  p('I owned requirements, rules, UI/UX, AI-assisted development, deployment, and QA on my own. Below are the three most important product trade-offs, and the bar I used to judge whether it “works.”')+
  '<div class="schedule-build-grid">'+evidence('DECISION 01 / PLATFORM','Build inside LINE, not another app','Instructors and students already talk on LINE, so LINE LIFF lets students open a link and submit times without installing anything. Next.js and Supabase on the back end, deployed on Vercel.')+evidence('DECISION 02 / RULE PRIORITY','The order of scheduling rules','First guarantee each student’s base lessons → prioritize students with fewer available slots → keep the primary instructor where possible → three-day gap between a student’s lessons. Unplaceable lessons and reasons go to the instructor.')+evidence('DECISION 03 / NOT BUILT','What I deliberately left out','Student self-cancel or reschedule, automatic cross-instructor substitute matching, and bulk reshuffling of confirmed lessons—each would undermine timetable stability or the instructor’s authority.')+'</div>'+
  '<div class="schedule-metrics"><span>SUCCESS METRICS / HOW I JUDGE WHETHER IT WORKS</span><div><div><strong>40/40</strong><p><b>Placement rate</b>Sample data: 10 students × 4 lessons all placed in one auto-scheduling run</p></div><div><strong>To measure</strong><p><b>Manual edits</b>How many lessons the instructor changes after the draft</p></div><div><strong>To measure</strong><p><b>Time to final</b>From collecting availability to a confirmed timetable (currently 2–3 hours)</p></div></div></div>')+
 section('reflection','07','OUTCOME & REFLECTION','From building a complete system to deciding what is worth building first',
  '<div class="schedule-learning"><span>WHAT I BUILT / CURRENT OUTCOME</span><strong>The first MVP turns scheduling constraints into a reviewable, editable timetable.</strong><p>It includes acceptable student times, primary-instructor targets, lesson spacing, draft allocation, and manual changes. I checked main rules and edge cases with simulated data.</p></div>'+
  '<div class="schedule-learning"><span>INITIAL DEMO FEEDBACK</span><strong>Generating a timetable does not mean the instructor wants to change her workflow.</strong><p>During the initial demo, she worried about teaching every student to use another tool and continuously managing cancellations and replacements.</p></div>'+
  '<div class="schedule-repo"><div><span>WORKING PRODUCT / SOURCE</span><strong>From concept to an interactive product</strong><p>Design, rules, and implementation are iterating. The current source code is available.</p></div><a href="'+repoURL+'" target="_blank" rel="noopener">Explore GitHub ↗</a></div>'+
  p('I started with one instructor’s scheduling challenge and gradually turned her requirements and exceptions into features. As development progressed, I kept adding rules in pursuit of a more complete system. The MVP demo exposed a deeper mistake: I had treated one person’s needs as product requirements before sufficiently checking which problems were shared across instructors or narrowing the minimum scope—and invested substantial time in development.')+
  p('A functional system also does not guarantee adoption. The instructor would still need to teach students a new tool, handle absences and make-up classes, and find substitutes in a LINE group. Without fitting those existing workflows, a faster first timetable might create more maintenance later.')+
  schedulingInsight('04','ADOPTION COST','Automation does not necessarily reduce work: learning and maintenance costs may offset scheduling efficiency gains.','Evaluation must cover student onboarding, instructor adjustments, and ongoing changes—not just the speed of generating a timetable.','adoption','Automation gains must be weighed against added upkeep.',true)+
  schedulingInsight('05','COLLABORATION','Scheduling depends on existing cross-role collaboration; a disconnected system may increase communication and upkeep.','Students, primary instructors, and substitutes already coordinate through LINE. The next step is to understand which habits should remain before choosing an integration approach.','collaboration','LINE is the existing communication channel.',true)+
  '<div class="schedule-reframe"><span>PRODUCT REFRAMING</span><h3>From “make scheduling faster” to “validate the most important problem with the smallest scope”</h3><p>I came to see that an MVP is not about quickly building as many features as possible. It is about testing the most important assumptions with limited investment. That changes my next product decisions.</p><div class="schedule-strategy-grid"><div><span>KEEP</span><strong>Central allocation and instructor review</strong><p>Retain the core ability to work with multiple constraints while testing whether it is a common need across instructors.</p></div><div><span>RETHINK</span><strong>Adoption and collaboration</strong><p>Learn which existing practices instructors are willing to change, then compare a standalone app, LINE integration, and hybrid flows.</p></div><div><span>DEFER</span><strong>Further feature expansion</strong><p>Avoid implementing every individual exception before confirming shared needs and adoption costs.</p></div></div></div>'+
  '<div class="schedule-next-steps"><span>NEXT VALIDATION / PLANNED, NOT COMPLETED</span><h3>Every step has a go / pivot threshold</h3><div class="schedule-next-steps-grid">'+evidence('01 / IS IT SHARED?','Interview five instructors of different sizes','Test whether scheduling time is a shared pain. Threshold: at least three spend over an hour a month and are willing to change—otherwise pivot.')+evidence('02 / CHEAPEST TEST','A month with a form and manual scheduling','Students submit times via a LINE form; I schedule by hand. Measure submission rate and how many lessons the instructor changes.')+evidence('03 / ADOPTION','Compare three adoption paths','Low-cost prototypes of a standalone app, an in-LINE flow, and a hybrid—finding the fewest habits people must change.')+evidence('04 / BUILD AGAIN','Resume development only after validation','Build only the validated core, tracking placement rate, manual edits, and time to final.')+'</div></div>'+
  '<div class="schedule-turn"><span>KEY TAKEAWAY</span><p><strong>From proving that I can build a product to learning what is worth building first.</strong> Building functionality does not mean I have found a product problem worth solving. Next time I will examine how widely the need is shared, which assumptions require early validation, and the cost of changing existing workflows before committing development resources.</p></div>'),

 kiosk:()=>
 section('overview','01','OVERVIEW','When KIOSK sales fell short, how could research inform the next product decisions?',
  p('The company had separate ordering and payment equipment and planned a next-generation integrated kiosk. Rather than transferring the old UI unchanged, the team needed to understand differences in restaurant menus, operational needs, and the relationship between onscreen prompts and physical payment hardware.')+
  ''+
  '<figure class="scenario-figure"><img src="./kiosk-scenario.png" alt="Conceptual integrated kiosk with display and payment hardware"><figcaption>Use scenario | how the screen relates to the physical payment hardware.</figcaption></figure>')+
 section('research','02','RESEARCH FRAMEWORK','Three research questions and the evidence behind them',
  '<div class="research-question-grid">'+
  '<div><span>RQ 01 / PRODUCT FIT</span><strong>What functions and flows do different restaurant formats need?</strong><div class="rq-decision"><b>Decision supported</b>Which store types and menu formats to assess first</div><div class="rq-value"><b>Potential business value</b>Better customer–product fit and fewer unsuitable deployments</div></div>'+
  '<div><span>RQ 02 / COMPETITIVE GAP</span><strong>Which important capabilities are missing against competitors?</strong><div class="rq-decision"><b>Decision supported</b>Baseline gaps and design opportunities</div><div class="rq-value"><b>Potential business value</b>A more competitive merchant offering</div></div>'+
  '<div><span>RQ 03 / USER EXPERIENCE</span><strong>Where do merchants report operating difficulties and unmet needs?</strong><div class="rq-decision"><b>Decision supported</b>Customer friction and potential staff-support burdens</div><div class="rq-value"><b>Potential business value</b>Fewer interrupted checkouts and smoother self-service</div></div></div>'+
  '<h3>Research Methods</h3><div class="research-method-grid">'+
  '<div class="research-method"><span>01 / DESK RESEARCH</span><strong>Restaurant segments and menus</strong><p>Mapped restaurant formats, menu structures, and ordering situations to understand fit.</p></div>'+
  '<div class="research-method"><span>02 / COMPETITIVE ANALYSIS</span><strong>Capabilities and interactions</strong><p>Compared functions, interfaces, and workflows to identify market conventions and product gaps.</p></div>'+
  '<div class="research-method"><span>03 / MERCHANT INTERVIEWS</span><strong>Seven partner-merchant managers and prior research</strong><p>Interviewed seven managers about reported customer friction and store needs; incorporated earlier findings about single-item/set-meal switching. No end customers were directly interviewed in this study.</p></div>'+
  '<div class="research-method"><span>04 / PROTOTYPE TESTING</span><strong>Six internal participants</strong><p>Asked six colleagues to use a prototype to detect early payment-flow and meal-option comprehension issues.</p></div></div>')+
 section('opportunity','03','RESEARCH FINDINGS','Market opportunities and the frictions behind actual ordering',
  '<div class="research-track research-track--market"><div class="findings-divider"><span>01 / MARKET & COMPETITIVE RESEARCH</span><h3>Market and competitor findings</h3><p>Exploratory store and competitor research informed which formats merited more attention.</p></div><h4 class="research-question-heading">Which restaurant formats should be assessed first?</h4>'+
  p('I scanned 40 stores across about ten formats to decide which store types the new machine should serve first. Chinese snack shops had simpler menu needs and large fast-food chains often run their own systems, so I focused on <strong>Japanese specialty and beverage shops</strong>, then screened by order frequency, standardization, and average order value.')+
  '<div class="market-evidence-group"><div class="market-evidence-heading"><span>MARKET OBSERVATION / EXPLORATORY</span><h5>Forty stores across ten formats</h5><p>Sample profile and adoption observations were examined together but use different counting units.</p></div><div class="market-compare"><div><span>40</span><strong>Stores</strong><small>Exploratory scan</small></div><div><span>10</span><strong>Formats</strong><small>Broad menu-based types</small></div><div><span>2</span><strong>Focus areas</strong><small>Japanese specialty / beverages</small></div></div>'+
  '<details class="evidence-details"><summary>Show: observed KIOSK adoption by format</summary><div class="market-chart"><div class="market-chart-head"><h6>Observed KIOSK adoption by restaurant format</h6><p>The first four bars have the highest observed counts—not a product-priority ranking.</p></div><div class="market-bars">'+
  [['Chinese casual eateries',7],['Japanese specialty',7],['Fast food',6],['Beverage shops',6],['Western restaurants',4],['Quick-service value meals',3],['Noodle shops',2],['Unmanned ramen',2],['Cafés',2],['Other',2]].map(function(d,i){return '<div class="market-bar-row"><span>'+d[0]+'</span><div class="market-bar-track"><div class="market-bar '+(i<4?'market-bar-lead':'')+'" style="width:'+Math.round(d[1]/7*100)+'%"></div></div><strong>'+d[1]+'</strong></div>'}).join('')+
  '</div><p class="market-chart-note">Source: early project market scan. Bar values are observed adopting brands by format, not the number of the 40 stores; do not add or generalize to nationwide adoption.</p></div></details></div>'+
  '<details class="evidence-details"><summary>Show: merchant screening criteria</summary><div class="market-filter-conclusion"><span>SEGMENT CRITERIA / RESEARCH-LED FILTERS</span><h5>Which merchants might be a better fit?</h5><p>Chinese snack shops seemed to require fewer specialized menu features, while large fast-food chains often rely on custom systems. I suggested evaluating Japanese specialty and beverage shops first, then checking transaction volume, workflow standardization, and average order value. These are screening hypotheses, not a ranking taken straight from the chart.</p><div class="segment-filters"><div><span>01 / TRANSACTION FREQUENCY</span><strong>High order frequency</strong><p>Concentrated peaks, quick ordering, and potentially high table turnover.</p></div><div><span>02 / STANDARDIZATION</span><strong>Standardized flows</strong><p>Relatively consistent menu and order steps that self-service could support.</p></div><div><span>03 / AVERAGE ORDER VALUE</span><strong>Under NT$300</strong><p>An initial business filter, not an established fact for all target restaurants.</p></div></div></div></details>'+
  '<div class="market-conclusion"><span>MARKET FOCUS</span><h4>From total addressable needs to formats worth assessing</h4><div class="market-sizing market-sizing--circles"><div class="market-sizing-tam"><span>TAM</span><strong>Restaurants needing self-service ordering</strong><div class="market-sizing-sam"><span>SAM</span><strong>Formats current product could serve</strong><div class="market-sizing-focus"><span>Initial focus</span><strong>Japanese specialty<br>Beverage shops</strong></div></div></div></div></div></div>'+
  '<div class="research-track research-track--interviews"><div class="findings-divider findings-divider--interviews"><span>02 / MERCHANT INTERVIEWS</span><h3>Merchant interviews and user needs</h3><p>Seven managers reported customer behavior and store needs.</p></div>'+
  '<div class="research-audience"><div class="research-audience-summary"><div class="research-audience-count"><strong>07</strong><span>Managers across four brands</span></div><div class="interview-brand-logos" aria-label="Interviewed restaurant logos"><img src="./kiosk-logo-mini-mono.svg" alt="mini STEAK HOUSE"><img src="./kiosk-logo-ippudo-mono.svg" alt="Ippudo"><img src="./kiosk-logo-lugu-mono.svg" alt="Fighting Chicken"><img src="./kiosk-logo-kokkio-mono.svg" alt="KOKKIO"></div></div><p>Representing Noble Family Steakhouse, KOKKIO, Ippudo, and Fighting Chicken. I synthesized their reports of customer behavior, plus support tickets and historical data, into user needs.</p></div>'+
  '<h4 class="research-question-heading">What problems did the interviews reveal?</h4>'+
  '<article class="insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">01</em><span>PAYMENT FRICTION</span></span><h4>Onscreen payment instructions and physical hardware are disconnected</h4><p>Managers said customers more often need help at payment than while choosing dishes. Attention stays on the screen, so cash, card, or contactless modules elsewhere on the machine can be missed.</p></div><figure><img src="./kiosk-visibility.png" alt="Conceptual line of sight from screen to payment hardware"><figcaption>Line-of-sight sketch | the gap between screen prompts and the payment module below.</figcaption></figure></article>'+
  '<figure class="research-voice research-voice--payment research-voice--verbatim"><span>ORIGINAL PARTICIPANT QUOTE / TRANSLATED</span><blockquote>I always have to tell them to put the money into the glowing blue spot.</blockquote></figure>'+
  '<article class="insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">02</em><span>MENU FLEXIBILITY</span></span><h4>A single menu structure cannot fit every restaurant format</h4><p>Customers know some standardized fast-food sets well, allowing defaults for required options. Other meals may need their full contents shown before a decision. Forcing the same choice sequence on every restaurant limits fit.</p></div><figure><img src="./kiosk-menu-simple.svg" alt="Different menu structures for steakhouse and breakfast formats"><figcaption>Left: preselect required options. Right: choose the main dish before deciding on a set.</figcaption></figure></article>'+
  '<figure class="research-voice research-voice--verbatim"><span>STEAKHOUSE / ORIGINAL QUOTE, TRANSLATED</span><blockquote>Could required meal options be selected by default?</blockquote><figcaption>Customers would only change extras or seasoning.</figcaption></figure>'+
  '<article class="insight-feature insight-feature--decision"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">03</em><span>PRIOR INTERVIEW FINDING</span></span><h4>Switching from an item to a set requires redundant work</h4><p>The existing product treated single items and sets as separate products. Changing one choice meant deleting the original and choosing again. This earlier insight was translated into a one-tap upgrade/switch concept in the redesign.</p></div><figure><img src="./kiosk-decision-revision.png" alt="Illustration of switching from item to set"><figcaption>Prior interview finding | changing between item and set requires repeated steps.</figcaption></figure></article><figure class="research-voice research-voice--verbatim"><span>ORIGINAL PARTICIPANT QUOTE / TRANSLATED</span><blockquote>Customers often decide to upgrade to a set at the end, so I ask them first.</blockquote></figure></div>')+
 section('solutions','04','PRODUCT RECOMMENDATIONS','Turn user evidence into product recommendations—not a feature wish list',
  p('I started from reported user problems and prior interviews, used competitor prevalence as supporting evidence, and checked implementation feasibility. A feature appearing in more than half of competitors was a potential market baseline, not an automatic development requirement. Popular-item suggestions were not central to ordering and membership integration may be costly, so I recommended further evaluation rather than claiming a fixed roadmap priority.')+
  '<div class="fact-grid">'+
  evidence('01 / USER NEEDS','User needs first','Use merchant reports and historical research to frame the real friction.')+
  evidence('02 / MARKET SIGNAL','Competitor prevalence corroborates','A common feature strengthens a supported need, but does not replace that evidence.')+
  evidence('03 / FEASIBILITY CHECK','Feasibility is a practical constraint','Discuss implementation and integration costs; the PM decides the final scope.')+'</div>'+
  "<div class=\"kiosk-decision-intro\"><span>RESEARCH TO DESIGN / DECISION MAKING</span><h3>Three decisions worth examining</h3><p>Of 12 recommendations, nine were adopted. These three connect to <strong>commercial opportunity, physical payment behavior, and ordering flexibility</strong>—rather than presenting every foundational feature as an equally significant result.</p></div><div class=\"kiosk-decision-grid\"><article class=\"kiosk-decision-card\"><span>01 / COMMERCIAL OPPORTUNITY</span><h4>Make add-ons discoverable at the right moment</h4><dl><div><dt>Evidence</dt><dd>Competitor research identified an opportunity to offer complementary items, but direct consumer demand was not established.</dd></div><div><dt>Decision</dt><dd>Provide a clear add-on entry during selection; any effect on average order value still needs post-launch validation.</dd></div></dl><small>Adopted design direction; not a shipped or measured outcome</small></article><article class=\"kiosk-decision-card\"><span>02 / SCREEN × HARDWARE</span><h4>Connect on-screen guidance to physical payment hardware</h4><dl><div><dt>Evidence</dt><dd>Merchant managers described customers focusing on the screen and struggling to locate cash, card, or contactless payment modules.</dd></div><div><dt>Decision</dt><dd>Map payment instructions to the actual module locations to potentially reduce staff assistance.</dd></div></dl><small>Adopted design direction; not a shipped or measured outcome</small></article><article class=\"kiosk-decision-card\"><span>03 / ORDER FLEXIBILITY</span><h4>Switch between items and sets without starting over</h4><dl><div><dt>Evidence</dt><dd>Earlier interviews found that upgrading a single item to a set often required deleting it and repeating choices.</dd></div><div><dt>Decision</dt><dd>Let customers switch within the existing selection, reducing repetitive work and the risk of abandoning an order.</dd></div></dl><small>Adopted design direction; not a shipped or measured outcome</small></article></div><div class=\"kiosk-foundation-note\"><span>FOUNDATIONAL IMPROVEMENTS</span><p>Other adopted improvements addressed menu category navigation, invoice/carrier entry, returning to order editing before payment, first-use hints, fewer payment steps, and scanning/pickup feedback. They support the overall flow without requiring separate case studies here. Three additional directions remained unconfirmed or required further evaluation.</p></div>")+
 section('validation','05','DESIGN & VALIDATION','From design recommendations to early usability feedback',
  '<div class="design-phase design-phase--proposal"><div class="phase-banner"><span>PHASE 01 / DESIGN PROPOSALS</span><strong>Translate evidence into screens</strong><p>Each design is explained in turn, with a clip recorded from the live demo on the right; at the end you can try the whole flow yourself.</p></div><article class="hl-row"><div class="hl-copy"><span class="solution-num">01 / MY PROPOSAL · ADOPTED BY THE PM</span><h3>Guide people to the physical payment module</h3><p>Abstract cash or card icons cannot show where the machine accepts payment. I proposed an illustration of the whole device with the relevant slot highlighted, so people can map the screen to the hardware.</p><p>I ranked it first because it was the only problem that sat in the main flow, interrupted the transaction, and pulled staff away—fixing it reduces both customer friction and store support cost.</p><figure class="hl-before"><img src="./kiosk-payment-before.png" alt="Old abstract payment guidance"><figcaption><b>Before</b> it only described the action, not where the module is.</figcaption></figure><div class="state-note">Contribution: I proposed the guidance based on merchant reports and UI analysis; the PM accepted it for prototyping. In the prototype test, payment was the part participants found smoothest.</div><a class="hl-try" href="#try-demo" data-demo-go="pay-cash">Try it in free play <span aria-hidden="true">↓</span></a></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-pay.jpg?v=1"><source src="./assets/kiosk-hl-pay.mp4?v=1" type="video/mp4"></video></div><figcaption>Cash payment: the camera moves to the coin slot, then the note acceptor</figcaption></figure></article><article class="hl-row"><div class="hl-copy"><span class="solution-num">02 / HISTORICAL RESEARCH REVIEW</span><h3>Switch between a single item and a meal set</h3><p>Earlier research found the existing system treated single items and sets as separate products, so changing your mind meant deleting and choosing again.</p><p>The redesign adds a one-tap upgrade/revert on the same product page, with sides adjusted on the same screen.</p><div class="state-note">Contribution: a team-generated direction that I helped assess and design.</div><a class="hl-try" href="#try-demo" data-demo-go="combo">Try it in free play <span aria-hidden="true">↓</span></a></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-combo.jpg?v=1"><source src="./assets/kiosk-hl-combo.mp4?v=1" type="video/mp4"></video></div><figcaption>Upgrading to a set and adjusting sides on the product page</figcaption></figure></article><article class="hl-row"><div class="hl-copy"><span class="solution-num">03 / ADOPTED DIRECTION</span><h3>Add-on purchase screen</h3><p>A separate add-on screen before checkout presents item photos, prices, and quantity controls.</p><p>A clear “No thanks” keeps upselling from becoming a barrier. It corresponds to the adopted “add-on purchase” recommendation.</p><a class="hl-try" href="#try-demo" data-demo-go="addon">Try it in free play <span aria-hidden="true">↓</span></a></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-addon.jpg?v=1"><source src="./assets/kiosk-hl-addon.mp4?v=1" type="video/mp4"></video></div><figcaption>The add-on screen appears before payment; add items or skip</figcaption></figure></article><div class="kiosk-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / FREE PLAY</span><h3>Walk through the redesigned ordering flow</h3><p>A working demo rebuilt from the Figma prototype: attract screen, dine-in or takeaway with table selection, ordering and set upgrades, add-ons, invoice options, and payment guidance animations matched to the kiosk hardware. Menu items, prices, and photos are sample data; payments are simulated; some details were added for the demo.</p><a href="./kiosk-demo/index.html?v=20261029" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · Not connected to a live system · Use the 展示用 (demo) buttons to simulate payment</small></div><div class="kiosk-live-frame"><iframe src="./kiosk-demo/index.html?v=20261029" title="Self-ordering kiosk interactive demo" loading="lazy"></iframe></div></div></div>'+
 '<div class="design-phase design-phase--testing"><div class="phase-banner"><span>PHASE 02 / PROTOTYPE TESTING</span><strong>Find comprehension gaps by observing tasks</strong><p>Six internal colleagues participated in the first usability test.</p></div><h3>Payment felt smooth; set-meal options were less clear</h3><p>The internal prototype test checked early understanding, not live customer performance.</p><figure class="design-shot test-session-photo"><img src="./kiosk-prototype-test.png" alt="Six internal colleagues testing a kiosk prototype"><figcaption>Prototype sessions on the kiosk hardware.</figcaption></figure>'+
  '<div class="test-finding-grid"><div class="test-finding-positive"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✓</b><span>POSITIVE SIGNAL</span></div><h4>Payment was relatively smooth</h4><p>Participants generally reported payment as one of the easiest task segments—a tentative signal supporting the flow.</p></div><div class="test-finding-negative"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✕</b><span>USABILITY ISSUE</span></div><h4>Uniform square buttons obscured their purpose</h4><p>Some testers were unsure what they were expected to configure after opening a set-meal option.</p></div></div></div>'+
  '<div class="design-phase design-phase--iteration"><div class="phase-banner"><span>PHASE 03 / SECOND ITERATION</span><strong>Test feedback led to new layouts</strong><p>Four presentation patterns replaced a one-size-fits-all square button.</p></div><div class="solution"><span class="solution-num">04 / SECOND DESIGN ITERATION</span><h3>Four layouts for different amounts and types of information</h3><p>Based on the first prototype’s comprehension issues, we stopped using one square button for everything and chose layouts with two questions: <strong>does the customer need a picture to decide, and do they need to change quantity?</strong> That produced four patterns and a consistent rule merchants can follow when setting up new menus.</p>'+
  '<div class="layout-variants"><figure><figcaption>Text choices | Rice portions or sweetness</figcaption><img src="./kiosk-layout-compact.png" alt="Text-only options"></figure><figure><figcaption>Horizontal cards | Items needing descriptions</figcaption><img src="./kiosk-layout-wide.png" alt="Horizontal product cards"></figure><figure><figcaption>Compact rows | Fast quantity changes</figcaption><img src="./kiosk-layout-row.png" alt="Compact horizontal item rows"></figure><figure><figcaption>Large image cards | Visually identifying set contents</figcaption><img src="./kiosk-layout-tile.png" alt="Image-rich large option tiles"></figure></div><div class="layout-rules"><span>DECISION RULE / WHICH LAYOUT FOR WHICH OPTION</span><div><b>Just choosing a level, no picture needed?</b><p>e.g. rice portion, sweetness, ice</p><strong>Text choices</strong></div><div><b>Needs a description to decide?</b><p>e.g. sides, add-on item details</p><strong>Horizontal cards</strong></div><div><b>Can pick several and adjust quantity?</b><p>e.g. extra sides, sauces</p><strong>Compact rows</strong></div><div><b>Needs a picture to recognize?</b><p>e.g. set-meal combinations</p><strong>Large image cards</strong></div></div><div class="state-note">Iteration status: the project ended after the second design round, without retesting.</div></div></div>')+
 section('reflection','06','OUTCOME & REFLECTION','Research matters when it clarifies decisions—and what remains unknown',
 '<div class="contribution-summary business-loop"><span class="overline">WHAT CHANGED / PRODUCT DECISIONS</span><p>I reframed disappointing kiosk sales into two distinct questions: <strong>feature completeness when merchants evaluate a product</strong>, and <strong>store support effort when customers get stuck</strong>. Alongside the commercial opportunity of add-ons, I prioritized payment-hardware guidance because it sits at a critical transaction moment and bridges digital instructions with physical equipment.</p></div>'+
 '<p>The key lesson was not the count of 12 recommendations, but learning to distinguish types of evidence. Competitor prevalence can indicate a market baseline, not prove user demand. Merchant reports reveal friction but need direct customer observation. A six-person colleague prototype test surfaces usability issues, not actual store performance.</p>'+
 '<div class="kiosk-reflection-evidence"><div><span>01 / RESEARCH REACH</span><h3>Gather direct customer evidence</h3><p>We interviewed seven merchant managers rather than end customers, and the 40-store scan was exploratory. A next step is to observe customers paying in different restaurant formats and validate target segments against merchant adoption data.</p></div><div><span>02 / PROTOTYPE VALIDITY</span><h3>Test the next iteration with real users</h3><p>Six internal colleagues tested the prototype, while the second round of set-selection layouts was not retested. Future testing should compare hesitation, selection errors, and switching between single items and sets with actual customers.</p></div><div><span>03 / OUTCOME MEASUREMENT</span><h3>Separate adoption from demonstrated value</h3><p>Nine recommendations being adopted is a design-decision outcome—not proof of shipping or impact. After rollout I would track payment help requests, completion, task time, add-on usage, and average order value.</p></div></div>'+
 '<p class="kiosk-reflection-close"><strong>Next step:</strong> connect research evidence, prototype testing, and operational metrics into one learning loop, so the work can demonstrate whether it truly reduces customer confusion and store workload.</p>'),
 kds:()=>
 section('overview','01','CONTEXT','From an engineering demo to a deliverable KDS: first understand what kitchens need',
  '<div class="role-split"><div><span>TEAM PROJECT (02–04)</span><strong>I owned research and UI review</strong><p>Synthesized historical research and customer feedback, analyzed competitors, and interviewed staff at LA PASTA; all five of my UI recommendations were adopted. Another UX designer led the production UI.</p></div><div><span>PERSONAL EXTENSION (05)</span><strong>My independent item-view concept</strong><p>Outside the project, I extended the batch-preparation insight into order/item views and batching rules, and built an interactive demo.</p></div></div>'+
  '<p>A customer expressed interest in buying a kitchen display system, so the company decided to turn an early demo—built by an engineer based on their own understanding—into a formal product. The prototype could show and process orders, but <strong>long dish names were truncated, scrolling text was hard to read, accidentally completed orders were difficult to recover, and oily hands made touch interaction cumbersome.</strong> The team first needed to clarify the initial scope and real kitchen workflows to turn the demo into a deliverable product.</p>'+
  '<figure class="scenario-figure kds-case-scenario"><img loading="lazy" src="./kds-case-hero.png" alt="Illustration of a cook using a kitchen display system"><figcaption>Kitchen use scenario.</figcaption></figure>')+
 section('research','02','DISCOVERY','How could we make evidence-based KDS decisions with a limited sample?',
  '<p>I triangulated <strong>feedback on the first-generation system, historical research, competitor comparisons, and contextual observation</strong> to understand preparation work and feature needs. LA PASTA was the only restaurant available for on-site research, so field data mainly adds working context.</p>'+
  '<h3>Research Methods</h3><div class="research-method-grid">'+
  '<div class="research-method"><span>01 / USER FEEDBACK & UX AUDIT</span><strong>Existing customer feedback and heuristic review</strong><p>Consolidated concerns about recovering mistakenly completed items, truncated long names, scrolling text, oily-hand touch interaction, and notifications; reviewed information density and interactions.</p></div>'+
  '<div class="research-method"><span>02 / HISTORICAL RESEARCH</span><strong>Earlier interviews and kitchen tickets</strong><p>Reviewed cross-restaurant interviews, kitchen tickets, and preparation behaviors to understand batching by shared process, sequencing, and role-specific information needs.</p></div>'+
  '<div class="research-method"><span>03 / COMPETITIVE ANALYSIS</span><strong>Feature and interaction comparisons</strong><p>Compared our first-generation Protech KDS with Eats365 and Weiby on views, grouping, sorting, timing, changes, and recovery to inform scope decisions.</p></div>'+
  '<div class="research-method"><span>04 / CONTEXTUAL OBSERVATION</span><strong>LA PASTA interviews and observation</strong><p>Observed how front- and back-of-house staff use multiple displays to coordinate preparation.</p></div></div>'+
  '<div class="kds-competitor-analysis"><h3>Competitive Analysis</h3><p>Using the <strong>Protech first-generation KDS</strong> as our baseline, I compared <strong>Eats365</strong> and <strong>Weiby</strong> across order grouping, sorting, legibility, change notifications, and serving status. The goal was to identify missing essentials and viable patterns—not simply copy the longest feature list.</p>'+
  '<div class="kds-research-turn"><strong>Key takeaway:</strong> a KDS helps the kitchen make fast decisions about <strong>grouping, sequencing, and recognition</strong> under pressure, while ensuring significant changes and serving states are noticed.</div>'+
  '<div class="kds-competitor-findings">'+
  '<article><span>01 / GROUPING</span><h4>Group information by the unit of work</h4><p>Orders are often arranged by order or table. Eats365 also offers category grouping and an aggregate view, helping cooks focus on batches of similar dishes. A grouping mode corresponds to a different working unit.</p></article>'+
  '<article><span>02 / SORTING</span><h4>Balance preparation efficiency with waiting fairness</h4><p>Sorting may use order number, table, order time, or elapsed wait. Eats365 supports menu-based order; Weiby offers pickup-time sorting and pre-order handling to inform when preparation should begin.</p></article>'+
  '<article><span>03 / READABILITY</span><h4>Stable legibility matters more than configurability</h4><p>In the old Protech UI, certain field and text-size settings truncated long item names. Eats365 offers an alternate tradeoff: a more fixed layout with default views to preserve readable, complete information.</p></article>'+
  '<article><span>04 / ALERTS & STATUS</span><h4>Changes and serving status must travel beyond a static screen</h4><p>Eats365 uses sound for cancellations and marks changed order details, reducing repeated comparison work. Both competitors support preparation progress; Weiby extends certain states into the ordering flow.</p></article></div>'+
  '<a class="kds-compare-button" href="./kds-function-comparison.webp" target="_blank" rel="noopener noreferrer" aria-label="Open complete KDS feature comparison">View full competitor feature comparison <span aria-hidden="true">↗</span></a></div>')+
 section('user-analysis','03','USER ANALYSIS','How do kitchens batch dishes, notice changes, and determine serving order?',
  '<p>I formed an initial picture from <strong>historical tickets and requirements</strong>, then interviewed <strong>two front- and back-of-house participants at LA PASTA</strong> during one contextual site visit. The three insights below synthesize these different evidence sources.</p>'+
  '<div class="kds-user-metrics"><div><strong>Historical evidence</strong><span>Kitchen tickets and prior needs</span></div><div><strong>2 people</strong><span>LA PASTA front/back of house</span></div><div><strong>1 visit</strong><span>Contextual field study</span></div></div>'+
  '<h3>Interviews & Field Study</h3><div class="kds-field-site"><img loading="lazy" src="./la-pasta-logo.svg" alt="LA PASTA restaurant logo"><div><span>FIELD STUDY / RESEARCH SITE</span><strong>LA PASTA</strong><p>Our sole on-site interview and observation location.</p></div></div>'+
  '<h3>Three Key Insights</h3><div class="kds-user-insights">'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">01</em><span>BATCH PREPARATION</span></span><h4>Kitchen staff batch dishes with the same preparation process instead of finishing one order at a time</h4><p>Cooks check quantities of similar items across orders before collecting ingredients and preparing them together. Where refrigerators and cooking stations are apart, gathering ingredients in a batch reduces back-and-forth movement. The kitchen’s unit of work may be a batch of dishes, not an entire ticket.</p></div><figure class="kds-insight-figure"><div class="kds-mini-flow"><div><small>Order 01</small><strong>Dish A × 2</strong></div><div><small>Order 02</small><strong>Dish A × 1</strong></div><span class="kds-mini-arrow">↓</span><div class="kds-mini-highlight"><small>Combined preparation</small><strong>Dish A × 3</strong></div></div><figcaption>Batching logic.</figcaption></figure></article>'+
  '<figure class="kds-insight-context voice-paraphrase"><span>WORKING CONTEXT / FROM RESEARCH NOTES</span><p class="voice-text">With the refrigerator some distance from the cooking area, cooks check total demand for similar dishes and collect ingredients in one trip.</p></figure>'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">02</em><span>INTERRUPTED ATTENTION</span></span><h4>Cooks glance at the screen intermittently; significant changes cannot rely on silent updates</h4><p>Attention stays primarily on ingredients and cooking, not the KDS. Cancellations or edits that require repeatedly checking the display risk going unnoticed. Food residue and oily hands also make frequent touch interactions inconvenient.</p></div><figure class="kds-insight-figure"><div class="kds-attention-flow"><div><b>Preparing</b><span>Focus on food</span></div><div class="kds-attention-alert"><b>Order change</b><span>Must be noticed</span></div><div><b>Look back</b><span>Adjust the task</span></div></div><figcaption>Intermittent attention sequence.</figcaption></figure></article>'+
  '<figure class="kds-insight-context voice-paraphrase"><span>WORKING CONTEXT / FROM CUSTOMER FEEDBACK</span><p class="voice-text">Kitchen staff cannot watch the screen all the time. An audible cancellation or edit alert could help them react in time.</p></figure>'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">03</em><span>EFFICIENCY & FAIRNESS</span></span><h4>Serving sequence must consider both production efficiency and customers’ waiting time</h4><p>Combining similar dishes speeds preparation, but does not mean all identical items belong in one endless batch. Orders placed far apart in time need to remain distinguishable; a total item count alone obscures who has waited longer.</p></div><figure class="kds-insight-figure"><div class="kds-time-flow"><div><small>Earlier order</small><strong>12:00</strong><span>Dish A</span></div><div><small>Next order</small><strong>12:03</strong><span>Dish A</span></div><div class="kds-time-later"><small>Later order</small><strong>12:18</strong><span>Dish A</span></div></div><figcaption>Example order times.</figcaption></figure></article></div>'+
  '')+
 section('opportunity','04','PRODUCT DECISIONS','Team project | Translating research into actionable next-version directions',
  '<p>The first-phase MVP focuses on <strong>understanding preparation information, recovering from mistakes, and batching dishes</strong>. Existing feedback and competitor research informed directions for legibility, change alerts, order recovery, synchronized views, and fewer touch actions. These recommendations entered planning, and the product is in development and preparing for customer handoff. <strong>Another UX designer owns the main production UI. My role was research, scope discussion, and five UI review recommendations.</strong></p>'+
  '<h3>From insights to MVP delivery scope</h3><p>I grouped needs into three challenges: <strong>recognize information and prevent errors, support batched preparation, and make critical changes noticeable</strong>. With first-phase engineering constraints, the team narrowed the MVP to two delivery goals; later needs remain candidates, not commitments.</p>'+
  "<div class=\"kds-scope-heading\"><div><span>PHASED DELIVERY</span><h3>Nested circles show phased delivery goals</h3><p>Closer to the center means planned earlier, <strong>not more important</strong>. Only the center represents the current MVP scope; the other layers are possible future directions.</p></div></div>"+
  "<div class=\"kds-scope-layout\"><div class=\"kds-scope-rings\" role=\"img\" aria-label=\"Three bottom-aligned nested circles: MVP in the center, later store-level rules in the middle, and network resilience on the outside.\"><div class=\"kds-scope-outer\"><span>03 / FUTURE</span><strong>Network resilience</strong></div><div class=\"kds-scope-middle\"><span>02 / LATER</span><strong>Store-specific preparation rules</strong></div><div class=\"kds-scope-center\"><span>01 / THIS MVP</span><strong>Readable preparation data<br>and error recovery</strong><strong>Batch preparation</strong></div></div><div class=\"kds-scope-legend\"><div><span class=\"kds-scope-dot kds-scope-dot--now\"></span><div><small>01 / First delivery MVP</small><strong>Core preparation tasks</strong><p>Prioritize clear information, safer actions, and batch preparation. This is <strong>planned scope</strong>, not a shipped feature set.</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--later\"></span><div><small>02 / Later workflow management</small><strong>Rules reflecting store practices</strong><p>Explore per-item batch limits (e.g. three servings) and splitting batches by order-time difference (e.g. ten minutes). These are examples, not confirmed default rules or MVP commitments.</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--future\"></span><div><small>03 / Future resilience</small><strong>Handling network interruptions</strong><p>A longer-term direction outside the current MVP.</p></div></div></div></div>"+
  "<h3>How research supports product decisions</h3><p>This matrix distinguishes evidence, design directions, and decisions. “MVP core need” means a first-phase goal.</p>"+
  "<div class=\"decision-comparison\" role=\"region\" aria-label=\"KDS research evidence and product decisions\" tabindex=\"0\"><table><thead><tr><th scope=\"col\">Evidence and problem</th><th scope=\"col\">Design direction and expected value</th><th scope=\"col\">Decision status</th></tr></thead><tbody><tr><td><strong>Existing feedback + UI review</strong><p>Truncated dish names and scrolling text add reading burden.</p></td><td><strong>Improve preparation readability</strong><p>Clarify product names, quantities, and status hierarchy.</p></td><td><span class=\"decision-status\">Discussed for redesign</span></td></tr><tr><td><strong>User feedback + kitchen context</strong><p>Greasy screens increase accidental taps, and dismissed orders can be hard to recover.</p></td><td><strong>Prevent and recover from errors</strong><p>Keep order states manageable and information recoverable.</p></td><td><span class=\"decision-status decision-status--adopted\">MVP core need</span></td></tr><tr><td><strong>Historical interviews + LA PASTA fieldwork</strong><p>Kitchens prepare similar items together while retaining order context.</p></td><td><strong>Support batch preparation</strong><p>Group work by item or process while keeping source orders visible.</p></td><td><span class=\"decision-status decision-status--adopted\">MVP core need</span></td></tr><tr><td><strong>Historical research + competitor analysis</strong><p>Staff need to recognize waiting time, source orders, additions, and cancellations.</p></td><td><strong>Prioritization and change awareness</strong><p>Explore auditory and visual change signals, subject to testing.</p></td><td><span class=\"decision-status\">For further evaluation</span></td></tr></tbody></table></div>"+
  "<h3>Completed design revisions | UI Review</h3><p>The five recommendations I made during UI review, and the team’s revised production designs based on them.</p>"+
  "<div class=\"kds-ui-review\"><div><span>01 / SPACE ALLOCATION</span><strong>Reduce the station selector's footprint</strong><p>Station settings change infrequently but occupy prominent screen space.</p></div><div><span>02 / WAITING TIME</span><strong>Simplify waiting-time colors</strong><p>Use fewer signals to support faster interpretation.</p></div><div><span>03 / VISUAL PRIORITY</span><strong>Reserve warning colors for real alerts</strong><p>Frequent red and orange elements compete with critical information.</p></div><div><span>04 / INFORMATION DENSITY</span><strong>Reassess redundant details</strong><p>Revisit pending counts, area counts, and icons that repeat labels.</p></div><div><span>05 / NOTE USABILITY</span><strong>Prioritize note usability</strong><p>Low-frequency notes still need to be readable and actionable.</p></div></div><p><strong>All five recommendations were adopted</strong> and reflected in the new screens by the UX designer who owned the production UI.</p>"+
  "<figure class=\"kds-shot kds-ui-compare\"><div class=\"kds-compare-grid\"><div><span class=\"kds-compare-label\">BEFORE / Previous</span><a href=\"./kds-ui-before.png\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-before.png\" alt=\"Previous white KDS interface\"></a></div><div><span class=\"kds-compare-label\">AFTER / Revised</span><a href=\"./kds-ui-after.png\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-after.png\" alt=\"Revised dark KDS interface\"></a></div></div><figcaption>Information hierarchy and density changes. Select an image to enlarge.</figcaption></figure>")+
 section('solutions','05','INDEPENDENT EXPLORATION','Personal extension | Beyond the MVP: an item view that matches preparation rhythm',
  '<p>Outside the formal company scope, I examined a distinction: <strong>front-of-house teams track completed orders, while cooks may work by item and preparation process.</strong> Aggregating every identical item without limits, however, can hide order timing and exceed what the kitchen can make in one batch.</p>'+
  '<div class="kds-design-overview"><span>DESIGN OUTCOME / FULL SCREENS</span><h3>Switch between order and item views</h3><p>These are my independent interface explorations. Full screens appear first, followed by interaction details. Select an image to enlarge it.</p></div>'+
  '<div class="kds-design-gallery"><figure class="kds-shot"><div class="kds-design-screen-title"><span>01 / ORDER VIEW</span><strong>Order view</strong></div><a href="./kds-design-order-view.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-order-view.png" alt="Full KDS order-view design"></a><figcaption>Track dishes and completion by order, including elapsed time, notes, and item status.</figcaption></figure><figure class="kds-shot"><div class="kds-design-screen-title"><span>02 / ITEM VIEW</span><strong>Item view</strong></div><a href="./kds-design-item-view.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-item-view.png" alt="Full KDS item-view design"></a><figcaption>Aggregate similar items across orders for batch preparation while preserving the original order reference.</figcaption></figure></div><div class="demo-jump-row"><a class="demo-jump" href="#try-demo" data-demo-go="order">Try the order view <span aria-hidden="true">↓</span></a><a class="demo-jump" href="#try-demo" data-demo-go="prod">Try the item view <span aria-hidden="true">↓</span></a></div>'+
  '<div class="kds-design-feature"><div class="kds-design-feature-copy"><span>DESIGN DETAIL 01 / INFORMATION AWARENESS</span><h3>Keep a visible trace of important changes</h3><p>Cooks look at screens intermittently. The design uses visible change states and proposes audible notifications.</p></div><figure class="kds-shot"><a href="./kds-design-alert.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-alert.png" alt="KDS change-status design"></a><figcaption>Change notification concept.</figcaption></figure></div>'+
  '<div class="kds-design-feature"><div class="kds-design-feature-copy"><span>DESIGN DETAIL 02 / ERROR RECOVERY</span><h3>Recover accidentally completed items and resume preparation</h3><p>Under pressure, items can be selected or completed by mistake. The concept shows item-selection states and a flow to restore dishes from completed-order history, reducing the work of locating the task again.</p><a class="demo-jump" href="#try-demo" data-demo-go="done">Try recovery in the live demo <span aria-hidden="true">↓</span></a></div><div class="kds-design-recovery-grid"><figure class="kds-shot"><a href="./kds-design-recovery-select.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-recovery-select.png" alt="KDS item selection and completion states"></a><figcaption>In progress: item selection and completion states.</figcaption></figure><figure class="kds-shot"><a href="./kds-design-recovery-history.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-recovery-history.png" alt="KDS order history recovery design"></a><figcaption>Recover a task from completed-item history.</figcaption></figure></div></div>'+
  '<div class="kds-design-phase-two"><span>PHASE 02 / FUTURE EXPLORATION, NOT THIS MVP</span><h3>Set preparation batches using capacity and order times</h3><p>Future designs could limit the quantity per batch for each item and split batches when order times are too far apart. The concept uses a maximum of three portions and a ten-minute gap as examples.</p><div class="validation-plan"><span>HOW I WOULD VALIDATE IT / LOW-COST TEST</span><ol><li>Take one store’s historical orders from a single peak period.</li><li>Simulate service under three rules: order by order, unlimited aggregation, and 3 portions / 10-minute splits.</li><li>Compare the longest wait and the number of batches—does splitting reduce batches without noticeably increasing waits?</li><li>Review the simulation with kitchen staff to check the values against real pan capacity and rhythm.</li></ol></div><figure class="kds-shot"><a href="./kds-design-phase-two.png" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-phase-two.png" alt="KDS phase-two capacity and time batching concept"></a><figcaption>Concept only: configurable batch capacity and time constraints.</figcaption></figure></div>')+
 section('reflection','06','OUTCOME & REFLECTION','From market-baseline features to understanding kitchen constraints',
  '<div class="kiosk-live-demo kds-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / INTERACTIVE DEMO</span><h3>Operate the kitchen display directly</h3><p>A working demo rebuilt from my independent Figma explorations: order, category, and item views; marking items in progress or done; undoing a completed order; sending served items back for a remake; scheduled orders that move into production automatically; and wait-time color coding with its settings. Orders are simulated, and new ones arrive periodically while intake is on. Some interaction details were added for the demo.</p><a href="./kds-demo/index.html" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · Not connected to a live system · Tap an item to start it, tap the circle to finish it</small></div><div class="kiosk-live-frame kds-live-frame"><iframe src="./kds-demo/index.html" title="Kitchen display system interactive demo" loading="lazy"></iframe></div></div>'+
  '<div class="kds-evidence-columns"><div><h3>What the company project has achieved so far</h3><ul><li>Competitor research, historical evidence, and contextual interviews informed new MVP decisions. Development is progressing toward customer delivery.</li><li>All five information-hierarchy and interaction review recommendations were adopted and reflected in revised UI designs.</li><li>Documented LA PASTA front/back-of-house coordination, production capacity, and timing constraints for further design work.</li></ul></div><div><h3>What still needs validation</h3><ul><li>Whether the new version actually reduces accidental completion or speeds recognition.</li><li>Whether other restaurant types need the same view switching and sequencing controls.</li><li>Whether my independent concepts—ten-minute grouping, item-specific capacity, and batch completion—work in practice (test plan in section 05).</li></ul></div></div>'+
  '<p>Competitor analysis established a market baseline, but could not explain why a particular feature mattered. Combined with historic feedback and field workflows, it became a foundation for actual design tradeoffs rather than a feature checklist.</p>'+
  '<p>Within the company project, I learned to translate research into information hierarchy discussions with another designer. Independently, I explored how <strong>order and item views, production capacity, and fairness of wait times</strong> could form an interactive concept. More restaurant contexts and usage evidence are needed before turning those rules into a product.</p>'+
  '<div class="kds-reflection-bottom"><strong>NEXT QUESTION ↗</strong><p>When kitchen and front-of-house rhythms differ, which steps should be automated, and which decisions should stay with people on site?</p></div>')

 };
 const card=(p,visual)=>`<a class="work-card" href="#/case/${p.id}">${visual(p.visual)}<div class="work-info"><div><h3>${p.title}</h3><p>${({scheduling:'Pilates scheduling platform',kiosk:'Next-generation self-ordering kiosk',kds:'Kitchen display system: team research + personal concept'})[p.id]}<br>${p.type}</p></div><div class="project-number">${p.number} / 03</div></div></a>`;
 function home(projects,visual){return `<section class="identity-hero"><div class="identity-wrap"><div class="identity-caption">PORTFOLIO / 2026</div><div class="identity-title"><span>Yuan</span><figure class="identity-photo"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><i class="corner c1"></i><i class="corner c2"></i><i class="corner c3"></i><i class="corner c4"></i></figure><span>Chi</span></div><div class="identity-details"><p>Product Manager ×<br>Product Designer</p><p>Research / Strategy / Design<br>From insight to working product</p><p>Based in Taiwan<br><a href="mailto:chi861008@gmail.com">chi861008@gmail.com ↗</a></p></div></div></section><section class="intro-portrait wrap" id="about"><div class="intro-copy"><div class="eyebrow">ABOUT ME</div><h2>Hi<span class="orange">.</span></h2><p>I am a product designer moving into product management. I break ambiguous business problems into testable assumptions, then use research, design, and working prototypes to help teams make trade-offs.</p><p>From B2B restaurant systems to building my own scheduling platform, I care about choosing a problem worth solving—and making the solution tangible.</p><a class="intro-link" href="#/about">More about me <span>↗</span></a></div><div class="intro-visual"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><div class="orbit-word">DESIGN · RESEARCH · PRODUCT · BUILD ·</div></div></section><section class="section-space wrap" id="work"><div class="section-head selected-head"><div><div class="eyebrow">SELECTED WORK / 2026</div><h2>Works record<span class="orange">.</span></h2></div><p>Three cases: research that shaped product decisions, a 0→1 build that taught me to re-scope, and team research extended into my own concept.</p></div><div class="work-grid identity-works">${projects.map(x=>card(x,visual)).join('')}</div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">THE WAY I THINK</div><h2>Fall in love with the problem, not the solution.</h2><p>I look for opportunities in evidence, connect user and business needs, and make abstract ideas testable through working products.</p><a href="mailto:chi861008@gmail.com">Let’s connect ↗</a></div></section>`;}
 function about(){return `<div class="wrap"><section class="case-top"><a class="back-link" href="#/">← HOME</a><div class="eyebrow" style="margin-top:75px">THE PERSON BEHIND THE WORK</div><h1>Curious.<br>Thoughtful.<br><span class="orange">Hands-on.</span></h1><p class="case-deck">A product designer with an industrial design background, moving into product management. I care less about screens alone and more about whether a problem is worth solving and which part to solve first—then I validate the answer with research and working prototypes.</p></section></div><section class="section-space wrap" id="about"><div class="about-mini"><div><div class="eyebrow">02 / ABOUT</div><h2>Curious by nature.<br>Builder by choice.</h2></div><div><p>My background spans industrial design, UX research, and digital product design across restaurant POS, self-ordering kiosks, and kitchen display systems. Moving into product management, I frame problems, set priorities, validate at the lowest cost, and build prototypes myself with AI-assisted development when needed.</p><p>I especially enjoy problem framing, finding connections across evidence, storytelling, and making complex interactions understandable.</p><div class="skills"><span class="chip">Product Discovery</span><span class="chip">Prioritization</span><span class="chip">UX Research</span><span class="chip">Product Design</span><span class="chip">Prototyping</span><span class="chip">AI-assisted Development</span></div></div></div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">LET’S CONNECT</div><h2>Have a product problem worth solving?</h2><p>I'd love to connect about product management, product design, and 0→1 opportunities.</p><a href="mailto:chi861008@gmail.com">Say hello ↗</a></div></section>`;}
 const caseLimits={kiosk:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>No end customers were interviewed; needs came from seven merchant managers</b><span>Observe customers in stores after launch and track payment-help requests. “Merchant report” items are my summaries; only the “original participant quote” is verbatim.</span></li><li><b>The prototype was tested with six colleagues; the second iteration was not retested</b><span>Run a second round with real customers, comparing hesitation and errors on set options.</span></li><li><b>The 40-store market scan is an exploratory sample</b><span>Validate the priority store types with sales and adoption data.</span></li><li><b>“Adopted” does not mean shipped</b><span>After launch, track payment completion, task time, and staff interventions.</span></li></ul></details>',scheduling:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Needs come from a single instructor</b><span>Interview five instructors of different sizes to test whether scheduling time is a shared pain.</span></li><li><b>Only functional tests with sample data; the instructor has not used it yet</b><span>Run one month of real scheduling and measure manual edits and time to final.</span></li><li><b>Time saved, fairness, cancellations, and the 120-lessons target are unvalidated</b><span>Track them as post-adoption metrics.</span></li></ul></details>',kds:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Field research covered one restaurant and two participants</b><span>Interview kitchens in other formats (fast food, beverages, set meals). “Working context” summaries are synthesized, not verbatim.</span></li><li><b>No post-launch usage data for the new version yet</b><span>Track mistaken-completion recoveries and order-recognition time.</span></li><li><b>My batching rules (3 portions, 10 minutes) are unvalidated</b><span>Simulate them with historical orders first—see section 05.</span></li></ul></details>'};
 function casePage(project,projects,visual){const next=projects[(projects.indexOf(project)+1)%projects.length],id=project.id;
 const snapshotMarkup=`<div class="case-overview-intro case-project-meta"><span>${id==='scheduling'?'Pilates Scheduling System · 2026 · Personal project':id==='kiosk'?'Next-generation Self-ordering Kiosk · Company project':'Kitchen Display System · Team project + personal extension'}</span></div>`+({"scheduling": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>A Pilates instructor spent 2–3 hours a month scheduling, then kept rescheduling after cancellations; letting students self-book increased cancellations.</p></div><div><span>MY ROLE</span><p>Independently defined requirements and scheduling rules, designed the UX/UI, and built a working system that runs inside LINE with AI-assisted development (Next.js, Supabase, LINE LIFF).</p></div><div><span>KEY DECISION</span><p>Replace first-come-first-served with “students submit acceptable times → system drafts the month → instructor finalizes,” keeping her judgment as the last step.</p></div><div><span>OUTCOME & TURN</span><p>With sample data, 10 students × 4 lessons were placed in one run (40/40). The demo showed adoption cost was the real barrier—I learned to validate shared needs before adding features.</p></div></div>", "kiosk": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>Existing KIOSK sales were below expectations. The company planned an integrated ordering-and-payment machine but did not know what the software should change first.</p></div><div><span>MY ROLE</span><p>Consumer-facing flow and UI designer; took part in the market scan, competitor analysis, seven merchant-manager interviews, and a six-person prototype test. I independently proposed the payment-hardware location guide.</p></div><div><span>KEY DECISION</span><p>Prioritize by merchant-reported user problems, weight by competitor prevalence, and gate by feasibility—narrowing 12 directions into priority recommendations instead of a feature list.</p></div><div><span>OUTCOME</span><p>Nine of 12 recommendations were adopted, including my payment-location guide. Payment was the smoothest part of the prototype test; confusion around set options drove four new option layouts.</p></div></div>", "kds": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>An engineer-built KDS demo had to become a deliverable product, but the team did not know how kitchens actually work or what the first release should cover.</p></div><div><span>MY ROLE</span><p><b>Team project:</b> research synthesis, competitor analysis, field interviews, and UI review; another UX designer led the production UI. <b>Personal extension:</b> I independently designed an item view and batching rules, and built an interactive demo.</p></div><div><span>KEY DECISION</span><p>Limit the MVP to two goals: readable preparation information with recoverable mistakes, and support for batch preparation. Sound alerts and store-specific rules come later.</p></div><div><span>OUTCOME</span><p>All five of my UI recommendations were adopted in the revised designs, and the product moved into pre-delivery. The personal extension is unvalidated.</p></div></div>"})[id];
 const deck={scheduling:'I built a working scheduling product—then learned from the instructor’s feedback to rethink what was worth building first.',kiosk:'Using research to decide what a next-generation kiosk should change first—from merchant interviews to an adopted payment-guidance design.',kds:'Research and UI review for a team KDS redesign (all five recommendations adopted), plus my own item-view concept for batch preparation.'}[id];
 const anchors=id==='kds'?['overview','research','user-analysis','opportunity','solutions','reflection']:id==='kiosk'?['overview','research','opportunity','solutions','validation','reflection']:['overview','research','opportunity','solutions','highlights','validation','reflection'];
 const date=id==='kiosk'?'2025.11 — 2026.04':id==='kds'?'2026.06 — 2026.07':project.year;
 const datetime=id==='kiosk'?'2025-11':id==='kds'?'2026-06':'2026';
 return `<div class="wrap"><section class="case-top${id==='kiosk'?' kiosk-cover':id==='kds'?' kds-cover':' scheduling-cover'}"><a href="#/work" class="back-link">← BACK TO SELECTED WORK</a><div class="case-title-row"><h1>${project.title}<span class="orange">.</span></h1><time class="case-cover-date" datetime="${datetime}">${date}</time></div><p class="case-deck">${deck}</p><a class="try-demo-cta" href="#try-demo">Try the demo <span aria-hidden="true">↓</span></a>${snapshotMarkup}</section><div class="case-layout"><aside class="side-index">${nav[id].map((t,i)=>`<a href="#${anchors[i]}"><b>0${i+1}</b>${t}</a>`).join('')}</aside><article class="case-article">${content[id]()}${id==='kiosk'?'':caseLimits[id]}</article></div><a class="next-case" href="#/case/${next.id}"><div><small>NEXT CASE STUDY →</small><h2>${next.title}</h2></div><span>↗</span></a></div>`;
 }
 return {home,about,casePage};
})();
